mapper.select:
SELECT r.id, r.paper_id AS paperId, r.title, r.abstract AS abstractText, p.title AS sourcePaperTitle, -- 【关键】表示“这篇论文引用了它” 1 - (r.embedding <=> cast(#{vectorStr} as vector)) AS score FROM paper_references r LEFT JOIN papers p ON r.paper_id = p.id WHERE r.embedding IS NOT NULL
AND r.paper_id = #{paperId}
ORDER BY r.embedding <=> cast(#{vectorStr} as vector) LIMIT #{topK}
